import 'package:flame_studio/repositories/repositories.dart';
import 'package:flutter_test/flutter_test.dart';

const _header = '''
// GENERATED CODE - DO NOT MODIFY BY HAND.
// Generated by Flame Studio.

// coverage:ignore-file
// ignore_for_file: type=lint

import 'dart:ui';

import 'package:flame/components.dart';

''';

void main() {
  group(ComponentCodeGenerator, () {
    const generator = ComponentCodeGenerator();

    test('fileName is the snake_case name of the component', () {
      expect(
        generator.fileName(const RectangleComponent(name: 'PlayerShip')),
        equals('player_ship.generated.dart'),
      );
    });

    test('generates a root without children', () {
      expect(
        generator.generate(
          const RectangleComponent(
            name: 'player',
            // The root position is set by whoever uses the component.
            position: ComponentPosition(x: 5, y: 5),
            size: ComponentSize(width: 10, height: 20.5),
          ),
        ),
        equals('''
$_header/// The `player` component.
class \$Player extends RectangleComponent {
  /// Creates a [\$Player].
  \$Player({super.position, super.angle, super.anchor, super.priority})
    : super(
        size: Vector2(10, 20.5),
        paint: Paint()..color = const Color(0xFFFFFFFF),
      );
}
'''),
      );
    });

    test('generates a getter for every child, and a class for children '
        'with children', () {
      expect(
        generator.generate(
          const RectangleComponent(
            name: 'player',
            children: [
              RectangleComponent(
                name: 'head',
                position: ComponentPosition(x: 10),
                paint: ComponentPaint(
                  color: 0x8000FF00,
                  style: PaintStyle.stroke,
                ),
                children: [
                  RectangleComponent(
                    name: 'eye',
                    size: ComponentSize(width: 5, height: 5),
                  ),
                ],
              ),
              RectangleComponent(
                name: 'left_arm',
                position: ComponentPosition(x: -4, y: 30),
              ),
            ],
          ),
        ),
        equals('''
$_header/// The `player` component.
class \$Player extends RectangleComponent {
  /// Creates a [\$Player].
  \$Player({super.position, super.angle, super.anchor, super.priority})
    : super(
        size: Vector2(50, 50),
        paint: Paint()..color = const Color(0xFFFFFFFF),
      ) {
    addAll([head, leftArm]);
  }

  /// The `head` child component.
  final \$PlayerHead head = \$PlayerHead();

  /// The `left_arm` child component.
  final RectangleComponent leftArm = RectangleComponent(
    position: Vector2(-4, 30),
    size: Vector2(50, 50),
    paint: Paint()..color = const Color(0xFFFFFFFF),
  );
}

/// The `head` child component of [\$Player].
class \$PlayerHead extends RectangleComponent {
  /// Creates a [\$PlayerHead].
  \$PlayerHead()
    : super(
        position: Vector2(10, 0),
        size: Vector2(50, 50),
        paint: Paint()
          ..color = const Color(0x8000FF00)
          ..style = PaintingStyle.stroke,
      ) {
    add(eye);
  }

  /// The `eye` child component.
  final RectangleComponent eye = RectangleComponent(
    position: Vector2(0, 0),
    size: Vector2(5, 5),
    paint: Paint()..color = const Color(0xFFFFFFFF),
  );
}
'''),
      );
    });

    test('generates position components without paints', () {
      expect(
        generator.generate(
          const PositionComponent(
            name: 'player',
            size: ComponentSize(width: 10, height: 20),
            children: [
              PositionComponent(
                name: 'body',
                position: ComponentPosition(x: 1, y: 2),
              ),
            ],
          ),
        ),
        equals(r'''
// GENERATED CODE - DO NOT MODIFY BY HAND.
// Generated by Flame Studio.

// coverage:ignore-file
// ignore_for_file: type=lint

import 'package:flame/components.dart';

/// The `player` component.
class $Player extends PositionComponent {
  /// Creates a [$Player].
  $Player({super.position, super.angle, super.anchor, super.priority})
    : super(size: Vector2(10, 20)) {
    add(body);
  }

  /// The `body` child component.
  final PositionComponent body = PositionComponent(
    position: Vector2(1, 2),
    size: Vector2(50, 50),
  );
}
'''),
      );
    });

    test('generates circles with a radius instead of a size', () {
      expect(
        generator.generate(
          const CircleComponent(
            name: 'ball',
            radius: ComponentRadius(radius: 10),
            children: [
              CircleComponent(
                name: 'core',
                position: ComponentPosition(x: 1, y: 2),
                radius: ComponentRadius(radius: 2.5),
                paint: ComponentPaint(
                  color: 0xFFFF0000,
                  style: PaintStyle.stroke,
                ),
              ),
            ],
          ),
        ),
        equals('''
$_header/// The `ball` component.
class \$Ball extends CircleComponent {
  /// Creates a [\$Ball].
  \$Ball({super.position, super.angle, super.anchor, super.priority})
    : super(radius: 10, paint: Paint()..color = const Color(0xFFFFFFFF)) {
    add(core);
  }

  /// The `core` child component.
  final CircleComponent core = CircleComponent(
    position: Vector2(1, 2),
    radius: 2.5,
    paint: Paint()
      ..color = const Color(0xFFFF0000)
      ..style = PaintingStyle.stroke,
  );
}
'''),
      );
    });

    test('generates polygons with their vertices', () {
      expect(
        generator.generate(
          const PolygonComponent(
            name: 'ship',
            children: [
              PolygonComponent(
                name: 'wing',
                position: ComponentPosition(x: 1, y: 2),
                vertices: ComponentVertices([
                  ComponentVertex(0, 0),
                  ComponentVertex(10, 0),
                  ComponentVertex(0, 2.5),
                ]),
              ),
            ],
          ),
        ),
        equals('''
$_header/// The `ship` component.
class \$Ship extends PolygonComponent {
  /// Creates a [\$Ship].
  \$Ship({super.position, super.angle, super.anchor, super.priority})
    : super([
        Vector2(25, 0),
        Vector2(50, 50),
        Vector2(0, 50),
      ], paint: Paint()..color = const Color(0xFFFFFFFF)) {
    add(wing);
  }

  /// The `wing` child component.
  final PolygonComponent wing = PolygonComponent(
    [Vector2(0, 0), Vector2(10, 0), Vector2(0, 2.5)],
    position: Vector2(1, 2),
    paint: Paint()..color = const Color(0xFFFFFFFF),
  );
}
'''),
      );
    });

    test('generates the angle of children, but not of the root', () {
      expect(
        generator.generate(
          const PositionComponent(
            name: 'player',
            // The root angle is set by whoever uses the component.
            angle: ComponentAngle(radians: 1),
            children: [
              PositionComponent(
                name: 'head',
                angle: ComponentAngle(radians: 0.5),
                children: [
                  PositionComponent(
                    name: 'eye',
                    angle: ComponentAngle(radians: 2),
                  ),
                ],
              ),
              PositionComponent(name: 'body'),
            ],
          ),
        ),
        equals(r'''
// GENERATED CODE - DO NOT MODIFY BY HAND.
// Generated by Flame Studio.

// coverage:ignore-file
// ignore_for_file: type=lint

import 'package:flame/components.dart';

/// The `player` component.
class $Player extends PositionComponent {
  /// Creates a [$Player].
  $Player({super.position, super.angle, super.anchor, super.priority})
    : super(size: Vector2(50, 50)) {
    addAll([head, body]);
  }

  /// The `head` child component.
  final $PlayerHead head = $PlayerHead();

  /// The `body` child component.
  final PositionComponent body = PositionComponent(
    position: Vector2(0, 0),
    size: Vector2(50, 50),
  );
}

/// The `head` child component of [$Player].
class $PlayerHead extends PositionComponent {
  /// Creates a [$PlayerHead].
  $PlayerHead()
    : super(position: Vector2(0, 0), angle: 0.5, size: Vector2(50, 50)) {
    add(eye);
  }

  /// The `eye` child component.
  final PositionComponent eye = PositionComponent(
    position: Vector2(0, 0),
    angle: 2,
    size: Vector2(50, 50),
  );
}
'''),
      );
    });

    test('generates the anchor of children, but not of the root', () {
      expect(
        generator.generate(
          const PositionComponent(
            name: 'player',
            // The root anchor is set by whoever uses the component.
            anchor: ComponentAnchor.center,
            children: [
              PositionComponent(
                name: 'head',
                anchor: ComponentAnchor.bottomCenter,
                children: [
                  PositionComponent(
                    name: 'eye',
                    anchor: ComponentAnchor(x: 0.25, y: 1),
                  ),
                ],
              ),
              PositionComponent(name: 'body'),
            ],
          ),
        ),
        equals(r'''
// GENERATED CODE - DO NOT MODIFY BY HAND.
// Generated by Flame Studio.

// coverage:ignore-file
// ignore_for_file: type=lint

import 'package:flame/components.dart';

/// The `player` component.
class $Player extends PositionComponent {
  /// Creates a [$Player].
  $Player({super.position, super.angle, super.anchor, super.priority})
    : super(size: Vector2(50, 50)) {
    addAll([head, body]);
  }

  /// The `head` child component.
  final $PlayerHead head = $PlayerHead();

  /// The `body` child component.
  final PositionComponent body = PositionComponent(
    position: Vector2(0, 0),
    size: Vector2(50, 50),
  );
}

/// The `head` child component of [$Player].
class $PlayerHead extends PositionComponent {
  /// Creates a [$PlayerHead].
  $PlayerHead()
    : super(
        position: Vector2(0, 0),
        anchor: Anchor.bottomCenter,
        size: Vector2(50, 50),
      ) {
    add(eye);
  }

  /// The `eye` child component.
  final PositionComponent eye = PositionComponent(
    position: Vector2(0, 0),
    anchor: Anchor(0.25, 1),
    size: Vector2(50, 50),
  );
}
'''),
      );
    });

    test('generates hitboxes with their collision, importing the Flame '
        'collisions', () {
      expect(
        generator.generate(
          const PositionComponent(
            name: 'player',
            children: [
              RectangleHitboxComponent(name: 'body'),
              CircleHitboxComponent(
                name: 'head',
                position: ComponentPosition(x: 1, y: 2),
                radius: ComponentRadius(radius: 5),
                collision: ComponentCollision(
                  type: HitboxCollisionType.passive,
                  isSolid: true,
                ),
              ),
              PolygonHitboxComponent(
                name: 'tail',
                vertices: ComponentVertices([
                  ComponentVertex(0, 0),
                  ComponentVertex(10, 0),
                  ComponentVertex(0, 10),
                ]),
                collision: ComponentCollision(
                  type: HitboxCollisionType.inactive,
                ),
              ),
            ],
          ),
        ),
        equals(r'''
// GENERATED CODE - DO NOT MODIFY BY HAND.
// Generated by Flame Studio.

// coverage:ignore-file
// ignore_for_file: type=lint

import 'package:flame/collisions.dart';
import 'package:flame/components.dart';

/// The `player` component.
class $Player extends PositionComponent {
  /// Creates a [$Player].
  $Player({super.position, super.angle, super.anchor, super.priority})
    : super(size: Vector2(50, 50)) {
    addAll([body, head, tail]);
  }

  /// The `body` child component.
  final RectangleHitbox body = RectangleHitbox(
    position: Vector2(0, 0),
    size: Vector2(50, 50),
  );

  /// The `head` child component.
  final CircleHitbox head = CircleHitbox(
    position: Vector2(1, 2),
    radius: 5,
    collisionType: CollisionType.passive,
    isSolid: true,
  );

  /// The `tail` child component.
  final PolygonHitbox tail = PolygonHitbox(
    [Vector2(0, 0), Vector2(10, 0), Vector2(0, 10)],
    position: Vector2(0, 0),
    collisionType: CollisionType.inactive,
  );
}
'''),
      );
    });

    test('imports dart:ui when any node has a paint', () {
      expect(
        generator.generate(
          const PositionComponent(
            name: 'player',
            children: [RectangleComponent(name: 'body')],
          ),
        ),
        allOf(
          startsWith(_header),
          contains('final RectangleComponent body = RectangleComponent('),
        ),
      );
    });

    test('pads colors to 8 hex digits', () {
      expect(
        generator.generate(
          const RectangleComponent(
            name: 'Ghost',
            paint: ComponentPaint(color: 0x00000001),
          ),
        ),
        contains('const Color(0x00000001)'),
      );
    });

    test('references the palette for palette colors', () {
      const palette = Palette(
        colors: [PaletteColor(name: 'dark_grey', color: 0xFF333333)],
      );

      final code = generator.generate(
        const RectangleComponent(
          name: 'Player',
          paint: ComponentPaint(paletteColor: 'dark_grey'),
          children: [
            CircleComponent(
              name: 'eye',
              paint: ComponentPaint(color: 0xFF0000FF),
            ),
          ],
        ),
        palette: palette,
      );

      expect(code, contains("import 'palette.generated.dart';"));
      expect(code, contains('paint: Paint()..color = GamePalette.darkGrey'));
      expect(code, contains('const Color(0xFF0000FF)'));
    });

    test('uses the color value when the palette color is missing', () {
      final code = generator.generate(
        const RectangleComponent(
          name: 'Player',
          paint: ComponentPaint(color: 0xFF00FF00, paletteColor: 'missing'),
        ),
      );

      expect(code, isNot(contains('palette.generated.dart')));
      expect(code, contains('const Color(0xFF00FF00)'));
    });
  });
}
